def allsame_transform(grid):
 h,w=len(grid),len(grid[0]); ct=Counter(v for row in grid for v in row); cand=[]
 for color in ct:
  nr=sum(sum(v==color for v in row)>=w*.5 for row in grid); nc=sum(sum(grid[r][c]==color for r in range(h))>=h*.5 for c in range(w))
  if nr+nc:cand.append((nr+nc,color))
 lc=min(cand)[1]; interior=max((c for c in ct if c!=lc),key=lambda c:ct[c]); rows=[r for r in range(h) if sum(v==lc for v in grid[r])>=w*.5]; cols=[c for c in range(w) if sum(grid[r][c]==lc for r in range(h))>=h*.5]; nodes=[[grid[r][c] for c in cols] for r in rows]
 marks=[(i,j) for i,row in enumerate(nodes) for j,v in enumerate(row) if v!=lc]; r0,r1=min(i for i,j in marks),max(i for i,j in marks);c0,c1=min(j for i,j in marks),max(j for i,j in marks);sub=[x[c0:c1+1] for x in nodes[r0:r1+1]]
 out=[]
 for i in range(len(sub)-1):
  row=[]
  for j in range(len(sub[0])-1):
   vals=[sub[i][j],sub[i][j+1],sub[i+1][j],sub[i+1][j+1]]
   row.append(vals[0] if vals[0]!=lc and len(set(vals))==1 else interior)
  out.append(row)
 return out
